import z3

def find_cubic_girth7_graph(n=26):
    """Find a cubic graph with girth >= 7 on n vertices using Z3."""
    # Variables for edges: e[i][j] for i < j
    e = {}
    for i in range(n):
        for j in range(i+1, n):
            e[(i, j)] = z3.Bool(f"e_{i}_{j}")

    solver = z3.Solver()

    # Each vertex has degree exactly 3
    for i in range(n):
        edges_i = []
        for j in range(n):
            if i < j:
                edges_i.append(e[(i, j)])
            elif j < i:
                edges_i.append(e[(j, i)])
        # Exactly 3 edges: sum = 3
        solver.add(z3.PbEq([(v, 1) for v in edges_i], 3))

    # No cycles of length <= 6
    # We need to forbid cycles of length 3,4,5,6

    # For cycles of length 3: i,j,k
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                solver.add(z3.Not(z3.And(e[(i,j)], e[(j,k)], e[(i,k)])))

    # Cycles of length 4: i-j-k-l-i with i<j<l and i != j,k,l
    print("Adding cycle4 constraints...")
    for i in range(n):
        for j in range(n):
            if j == i: continue
            for k in range(n):
                if k == i or k == j: continue
                for l in range(n):
                    if l == i or l == j or l == k: continue
                    if j < l:  # avoid duplicates
                        # edges: (i,j), (j,k), (k,l), (l,i)
                        # need i<j? we need to access correct variable
                        edges_cycle = []
                        for a, b in [(i,j), (j,k), (k,l), (l,i)]:
                            if a < b:
                                edges_cycle.append(e[(a,b)])
                            else:
                                edges_cycle.append(e[(b,a)])
                        solver.add(z3.Not(z3.And(*edges_cycle)))

    print("Cycle4 done, now cycle5...")
    # Cycles of length 5: too many combinations. Let's skip for now and see if we can get something.
    # Actually for n=26, number of 4-cycles is 26*25*24*23/8? That's large.
    # Let's try a different encoding.

    print("Number of variables:", len(e))

    # Actually, let's not add all cycle constraints naively.
    # Let's try a different approach: use a known construction or try local search.

    return solver, e

