def multiply(a, b):
    """Multiply two elements of D13 (0..25)."""
    # a = r^i or r^i*s
    if a < 13:  # a = r^i
        i = a
        if b < 13:  # b = r^j
            return (i + b) % 13  # r^{i+j}
        else:  # b = r^j * s
            j = b - 13
            return 13 + ((i + j) % 13)  # r^{i+j} * s
    else:  # a = r^i * s
        i = a - 13
        if b < 13:  # b = r^j
            return 13 + ((i - b) % 13)  # r^{i-j} * s (since s*r^j = r^{-j}*s)
        else:  # b = r^j * s
            j = b - 13
            return (i - j) % 13  # r^{i-j} (since s*r^j*s = r^{-j})

