def girth(adj, n):
    """Find length of shortest cycle using BFS from each vertex."""
    best = float('inf')
    for start in range(n):
        # BFS
        parent = [-1] * n
        dist = [-1] * n
        dist[start] = 0
        queue = [start]
        for v in queue:
            for u in adj[v]:
                if dist[u] == -1:
                    dist[u] = dist[v] + 1
                    parent[u] = v
                    queue.append(u)
                elif u != parent[v] and parent[u] != v:
                    # Found a cycle
                    cycle_len = dist[v] + dist[u] + 1
                    if cycle_len < best:
                        best = cycle_len
                        if best == 3:
                            return best
        if best <= 3:
            return best
    return best

